CREATE TABLE registro_institucional (
    caja_id uuid NOT NULL REFERENCES caja(id) ON DELETE CASCADE,
    categoria varchar(30) NOT NULL CHECK (categoria IN ('empresa', 'actas', 'accionistas')),
    registro_id varchar(100) NOT NULL,
    payload jsonb NOT NULL CHECK (jsonb_typeof(payload) = 'object'),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (caja_id, categoria, registro_id)
);
ALTER TABLE registro_institucional ENABLE ROW LEVEL SECURITY;
ALTER TABLE registro_institucional FORCE ROW LEVEL SECURITY;
CREATE POLICY registro_institucional_tenant ON registro_institucional FOR ALL
    USING (caja_id = app_caja_id() AND app_es_admin())
    WITH CHECK (caja_id = app_caja_id() AND app_es_admin());
GRANT SELECT, INSERT, UPDATE, DELETE ON registro_institucional TO app_rw;
GRANT SELECT ON registro_institucional TO app_ro;

