INSERT INTO registro_institucional (caja_id,categoria,registro_id,payload) VALUES ('a0000000-0000-0000-0000-000000000001','empresa','empresa','{"id":"a0000000-0000-0000-0000-000000000001","nombre":"Caja Emprende Chambala","nombreComercial":"UNICA Emprende Chambala","ruc":"20000000000","logo":"","fechaFundacion":"2021-06-08","fechaEmisionAcciones":"2021-06-08","descripcion":"Organización comunal de crédito y ahorro (UNICA) constituida con el propósito de fomentar el desarrollo económico solidario, la inclusión financiera, el respaldo a emprendimientos rurales y el fortalecimiento socioeconómico de los comuneros y productores del anexo de Chambala.","objetoSocial":"Intermediación financiera comunal, custodia del ahorro colectivo, otorgamiento de microcréditos para agricultura, ganadería, comercio y emergencias familiares, y reparto anual equitativo de utilidades según el número de acciones suscritas.","mision":"Proporcionar a los socios y comuneros de Chambala servicios financieros confiables, justos y accesibles que promuevan su autonomía económica, progreso productivo y seguridad familiar bajo principios de ayuda mutua y transparencia.","vision":"Consolidarse como la Caja Comunal y Unión de Crédito y Ahorro (UNICA) líder y autosostenible de la provincia de Concepción, reconocida por su solvencia, transparencia e impacto directo en el bienestar de la comunidad.","direccion":"Av. Principal S/N, Local Comunal de Chambala","distrito":"Lurigancho","provincia":"Lima","departamento":"Lima","pais":"Perú","telefono":"+51 964 123 456","email":"cajachambala@gmail.com","sitioWeb":"https://emprendechambala.pe","moneda":"PEN","diaReunion":8,"valorAccion":30,"representanteLegal":"PONCE HUILCAYA ADELA","cargoRepresentante":"Presidenta de Junta Directiva","tipoDocumentoRepresentante":"DNI","numeroDocumentoRepresentante":"09812345","partidaRegistral":"Partida Electrónica N° 00001 - SUNARP Chambala","updatedAt":"2026-10-10T18:01:40.819Z"}'::jsonb) ON CONFLICT (caja_id,categoria,registro_id) DO NOTHING;
INSERT INTO registro_institucional (caja_id,categoria,registro_id,payload) VALUES ('a0000000-0000-0000-0000-000000000001','actas','acta-001','{"id":"acta-001","numeroActa":"Acta N° 01-2021","tipo":"EXTRAORDINARIA","tipoTitulo":"Asamblea General de Constitución y Fundación","fecha":"2021-06-08","hora":"10:00","lugar":"Local Comunal del Anexo de Chambala","presidente":"PONCE HUILCAYA ADELA","secretario":"MORAN LAIME CIRILO","asistentes":28,"quorumPorcentaje":100,"agenda":["Constitución y fundación formal de la Caja Comunal Emprende Chambala (UNICA)","Aprobación del Estatuto y Reglamento Interno de Operaciones","Fijación del valor nominal de la acción en S/. 30.00","Elección e instalación de la primera Junta Directiva"],"acuerdos":["Aprobar por aclamación unánime la fundación de la Caja Comunal ''Emprende Chambala''.","Establecer el aporte de capital inicial y fijar el valor de la acción en treinta y 00/100 soles (S/. 30.00).","Fijar el día 08 de cada mes como fecha oficial de asamblea ordinaria de aportes y pagos de cuotas.","Elegir a la Junta Directiva presidida por Adela Ponce Huilcaya."],"resumen":"Reunión fundacional donde los comuneros de Chambala acuerdan constituir la UNICA con un capital inicial y aprueban las normas de ahorro y crédito.","archivoNombre":"Acta_01_2021_Constitucion_Firmada.pdf","archivoTipo":"application/pdf","archivoTamano":245000,"archivoData":"","fechaRegistro":"2021-06-08"}'::jsonb) ON CONFLICT (caja_id,categoria,registro_id) DO NOTHING;
